import type { World } from "../../engine";
import { Position, POSITION } from "../../engine/components/position";
import { LEVEL } from "../../engine/components/level";
import { MOVABLE } from "../../engine/components/movable";
import { RENDERABLE } from "../../engine/components/renderable";
import { SPRITE } from "../../engine/components/sprite";
import { CASTABLE } from "../../engine/components/castable";
import { DISPLACABLE } from "../../engine/components/displacable";
import { HOMING } from "../../engine/components/homing";
import { FRAGMENT } from "../../engine/components/fragment";
import { hasComponent, TypedEntity } from "../../engine/entities";
import { getCell } from "../../engine/systems/map";
import { getEnterable } from "../../engine/systems/enter";
import { normalize } from "../../game/math/std";
import { getClosestQuadrant } from "../../game/math/path";

export type SceneEntity = [
  number,
  number,
  boolean,
  string | number,
  TypedEntity<"POSITION">
];

export type SceneViewport = {
  position: Position;
  fraction: Position;
  overscan: Position;
  columns: number;
  rows: number;
  viewable?: { MOVABLE?: { flying?: boolean } } | null;
  structure?: number;
};

const isAnchoredSpell = (entity: TypedEntity, id: number) =>
  !!entity[CASTABLE] &&
  !entity[HOMING] &&
  !entity[DISPLACABLE] &&
  entity[CASTABLE].caster !== id;

export const collectScene = (
  world: World,
  {
    position,
    fraction,
    overscan,
    columns,
    rows,
    viewable,
    structure,
  }: SceneViewport,
  castableQuadrants: Record<number, Position>
): SceneEntity[] => {
  const size = world.metadata.gameEntity[LEVEL].size;
  const flyingPadding = viewable?.[MOVABLE]?.flying ? 4 : 0;
  const fractionX = Math.sign(fraction.x);
  const fractionY = Math.sign(fraction.y);

  const renderableEntities: SceneEntity[] = [];
  const left = position.x - Math.floor(columns / 2) - Math.max(0, overscan.x) -
    Math.max(0, fractionX) - flyingPadding / 2;
  const top = position.y - Math.floor(rows / 2) - Math.max(0, overscan.y) -
    Math.max(0, fractionY) - flyingPadding / 2;
  const right = left + columns + Math.abs(overscan.x) + Math.abs(fractionX) + flyingPadding;
  const bottom = top + rows + Math.abs(overscan.y) + Math.abs(fractionY) + flyingPadding + 1;
  for (let renderedX = left; renderedX < right; renderedX++) {
    for (let renderedY = top; renderedY < bottom; renderedY++) {
      const renderedPosition = { x: renderedX, y: renderedY };
      const cell = getCell(world, renderedPosition);
      const inside =
        !!structure &&
        getEnterable(world, renderedPosition)?.[FRAGMENT]?.structure ===
          structure;

      for (const entityId in cell) {
        const entity = cell[entityId] as TypedEntity<"POSITION">;

        // render anchored spells separately
        if (
          !hasComponent(entity, RENDERABLE) ||
          !hasComponent(entity, SPRITE) ||
          isAnchoredSpell(entity, Number(entityId))
        )
          continue;

        renderableEntities.push([
          renderedX,
          renderedY,
          inside,
          entityId,
          entity,
        ]);
      }
    }
  }

  // given that hero is positioned absolutely,
  // find closest quadrant to virtually place all castables
  const castableEntities = world.getEntities([CASTABLE, POSITION]);
  for (const entity of castableEntities) {
    const entityId = world.getEntityId(entity);

    const tornado = entity.SEQUENCABLE?.states.tornado;
    if (tornado) {
      // Gusts keep their original radius while the eye shrinks or moves.
      const reach = 1 + tornado.args.gusts.reduce(
        (radius, gust) => Math.max(radius, gust.radius), tornado.args.radius
      );
      const eye = entity[POSITION];
      const firstX = left - reach + normalize(eye.x - left + reach, size);
      const firstY = top - reach + normalize(eye.y - top + reach, size);
      for (let x = firstX; x < right + reach; x += size) {
        for (let y = firstY; y < bottom + reach; y += size) {
          if (x >= left && x < right && y >= top && y < bottom) continue;
          const inside = !!structure &&
            getEnterable(world, eye)?.[FRAGMENT]?.structure === structure;
          renderableEntities.push([x, y, inside, String(entityId), entity]);
        }
      }
      continue;
    }
    if (!isAnchoredSpell(entity, entityId)) continue;

    let castableQuadrant = castableQuadrants[entityId];

    // check if quadrant has been calculated before
    if (!castableQuadrant) {
      const normalizedX = normalize(position.x, size);
      const normalizedY = normalize(position.y, size);
      const { quadrant } = getClosestQuadrant(
        { x: normalizedX, y: normalizedY },
        entity[POSITION],
        size,
        1
      );
      const wrapX = Math.floor((position.x - normalizedX) / size);
      const wrapY = Math.floor((position.y - normalizedY) / size);
      castableQuadrant = {
        x: wrapX + quadrant.x,
        y: wrapY + quadrant.y,
      };
      castableQuadrants[entityId] = castableQuadrant;
    }

    renderableEntities.push([
      entity[POSITION].x + castableQuadrant.x * size,
      entity[POSITION].y + castableQuadrant.y * size,
      !!structure,
      entityId,
      entity,
    ]);
  }

  return renderableEntities;
};
